SET TIME ZONE 'UTC';
WITH meses AS (SELECT generate_series(DATE '2023-01-01',DATE '2025-12-01','1 month')::date mes), classificado AS (SELECT p.pedido_id,date_trunc('month',p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date mes,case when p.cliente_id is null then 'convidado' when row_number() over(partition by p.cliente_id order by p.data_pedido,p.pedido_id)=1 then 'primeira_compra' else 'recorrente' end estagio FROM pedidos p WHERE p.status_logistico<>'CANCELADO'), valores AS (SELECT c.mes,c.estagio,m.receita_mercadoria_pre_devolucao receita FROM classificado c JOIN vw_pedidos_metricas m USING(pedido_id)), a AS (SELECT mes,coalesce(sum(receita) FILTER(WHERE estagio='convidado'),0) receita_convidado,coalesce(sum(receita) FILTER(WHERE estagio='primeira_compra'),0) receita_primeira_compra,coalesce(sum(receita) FILTER(WHERE estagio='recorrente'),0) receita_recorrente FROM valores GROUP BY mes) SELECT m.mes,coalesce(a.receita_convidado,0) receita_convidado,coalesce(a.receita_primeira_compra,0) receita_primeira_compra,coalesce(a.receita_recorrente,0) receita_recorrente,coalesce(a.receita_convidado,0)+coalesce(a.receita_primeira_compra,0)+coalesce(a.receita_recorrente,0) receita_total,100*coalesce(a.receita_convidado,0)/nullif(coalesce(a.receita_convidado,0)+coalesce(a.receita_primeira_compra,0)+coalesce(a.receita_recorrente,0),0) pct_convidado,100*coalesce(a.receita_primeira_compra,0)/nullif(coalesce(a.receita_convidado,0)+coalesce(a.receita_primeira_compra,0)+coalesce(a.receita_recorrente,0),0) pct_primeira_compra,100*coalesce(a.receita_recorrente,0)/nullif(coalesce(a.receita_convidado,0)+coalesce(a.receita_primeira_compra,0)+coalesce(a.receita_recorrente,0),0) pct_recorrente FROM meses m LEFT JOIN a USING(mes) ORDER BY m.mes;
